(()=>{'use strict';const CASES=[{href:'/studii-de-caz/castig-loto-roma-2020/',eyebrow:'STUDIU REAL · LOTO',title:'Câștig la LOTO · Roma 2020',meta:'Eveniment biografic · analiză retrospectivă',lead:'Timingul astrologic al unui câștig real, analizat retrospectiv.',symbol:'★'},{href:'/studii-de-caz/interventie-chirurgicala-pitesti-1998/',eyebrow:'STUDIU REAL · TIMING',title:'Intervenție chirurgicală · Pitești 1998',meta:'6 august 1998 · Arce Solare + tranzite',lead:'Pluto–Soare, Saturn–Lună și Marte–Ascendent, analizate retrospectiv, fără concluzii medicale.',symbol:'✚'},{href:'/local-space/studii-de-caz/soare-calarasi-108/',eyebrow:'LOCAL SPACE · SOARE',title:'Soare → Călărași',meta:'Azimut 108° · aliniere foarte exactă',lead:'Direcția solară București–Călărași, analizată ca reper Local Space.',symbol:'☉'},{href:'/local-space/studii-de-caz/luna-sulina-73/',eyebrow:'LOCAL SPACE · LUNĂ',title:'Lună → Sulina',meta:'Azimut 73° · coridor aproape perfect',lead:'Linia Lunii spre Sulina, cu o abatere de aproximativ o zecime de grad.',symbol:'☽'},{href:'/local-space/studii-de-caz/venus-constanta-98/',eyebrow:'LOCAL SPACE · VENUS',title:'Venus → Constanța',meta:'Azimut 98° · orb ≈0,5°',lead:'Alinierea venusiană București–Constanța, analizată separat în seria Local Space.',symbol:'♀'},{href:'/local-space/studii-de-caz/jupiter-iasi-17/',eyebrow:'LOCAL SPACE · JUPITER',title:'Jupiter → Iași',meta:'Azimut 17,5° · orb ≈2,6°',lead:'Coridor jupiterian asociat simbolic cu expansiunea, educația și oportunitățile.',symbol:'♃'}];const card=(c,i)=>{const a=document.createElement('a');a.className='av-case-showcase-card av-case-local-space';a.href=c.href;a.setAttribute('aria-label','Vezi studiul de caz '+c.title);a.innerHTML=`<div class="av-case-showcase-visual av-case-local-space-visual" aria-hidden="true"><span class="av-case-local-space-symbol">${c.symbol}</span><span class="av-case-local-space-orbit"></span><span class="av-case-local-space-index">${String(i+4).padStart(2,'0')}</span></div><div class="av-case-showcase-copy"><p class="av-case-showcase-eyebrow">${c.eyebrow}</p><h3>${c.title}</h3><p class="av-case-showcase-meta">${c.meta}</p><p class="av-case-showcase-lead">${c.lead}</p><span class="av-case-showcase-cta">VEZI STUDIUL →</span></div>`;return a};const install=()=>{const section=document.getElementById('studii-de-caz-home'),track=section&&section.querySelector('.av-case-showcase-grid');if(!track||track.dataset.avLocalSpaceAdded==='1')return false;const heading=section.querySelector('#av-case-showcase-title,.av-case-showcase-head h2,.av-case-lux-head h2');if(heading)heading.textContent='STUDII DE CAZ REALE';track.dataset.avLocalSpaceAdded='1';const existing=new Set([...track.querySelectorAll('a[href]')].map(a=>a.getAttribute('href')));CASES.filter(c=>!existing.has(c.href)).forEach((c,i)=>track.appendChild(card(c,i)));let style=document.getElementById('av-local-space-cases-style');if(!style){style=document.createElement('style');style.id='av-local-space-cases-style';style.textContent=`#studii-de-caz-home .av-case-local-space-visual{display:grid!important;place-items:center!important;background:radial-gradient(circle at 50% 44%,rgba(57,255,20,.12),transparent 24%),radial-gradient(circle at 50% 50%,#13251a 0,#07110d 52%,#020403 100%)!important}#studii-de-caz-home .av-case-local-space-symbol{position:relative;z-index:2;color:#f1d36e;font:700 clamp(76px,9vw,132px)/1 Georgia,serif;text-shadow:0 0 18px rgba(231,198,106,.32),0 0 42px rgba(57,255,20,.12)}#studii-de-caz-home .av-case-local-space-orbit{position:absolute;width:48%;aspect-ratio:1;border:1px solid rgba(231,198,106,.38);border-radius:50%;box-shadow:0 0 0 22px rgba(57,255,20,.025),0 0 0 44px rgba(231,198,106,.018)}#studii-de-caz-home .av-case-local-space-index{position:absolute;right:14px;bottom:12px;z-index:3;color:rgba(255,244,200,.7);font:900 11px/1 Inter,system-ui,sans-serif;letter-spacing:.12em}@media(max-width:820px){#studii-de-caz-home .av-case-local-space-symbol{font-size:86px}#studii-de-caz-home .av-case-local-space-orbit{width:42%}}`;document.head.appendChild(style)}section.dispatchEvent(new CustomEvent('astrovip:cases-expanded',{bubbles:true,detail:{count:track.querySelectorAll('.av-case-showcase-card').length}}));return true};let tries=0;const timer=setInterval(()=>{tries++;if(install()||tries>80)clearInterval(timer)},100);if(document.readyState!=='loading')install();else document.addEventListener('DOMContentLoaded',install,{once:true})})();